command:
set -e
cmp /workspace/package-lock.json /candidate-lock.json
node --input-type=module - <<'JS'
import fs from 'node:fs';import assert from 'node:assert/strict';
const before=JSON.parse(fs.readFileSync('package.json')),after=JSON.parse(fs.readFileSync('/candidate-package.json'));
for(const key of ['preinstall','install','postinstall','prepare'])assert.equal(before.scripts?.[key],after.scripts?.[key]);
delete before.scripts;delete after.scripts;assert.deepEqual(before,after);
fs.copyFileSync('/candidate-package.json','package.json');
JS
test ! -e /workspace/dist/local
npm run typecheck
npm run test:preflight
npm run test:qualification
node --test --test-concurrency=1 tooling/test-node.test.mjs
npm run verify:imports
